```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int maxDl = 1, maxStart = 0;
    int curDl = 1, curStart = 0;

    for (int i = 1; i < n; i++) {
        if (T[i] % 2 == T[i - 1] % 2) {
            curDl++;
        } else {
            if (curDl > maxDl) {
                maxDl = curDl;
                maxStart = curStart;
            }
            curDl = 1;
            curStart = i;
        }
    }
    if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }

    cout << "Najdluzsza seria:" << endl;
    cout << "Dlugosc: " << maxDl << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "Typ: " << (T[maxStart] % 2 == 0 ? "parzyste" : "nieparzyste") << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Klasyczny wzorzec current/max. Warunek kontynuacji serii: ta sama parzystosc co poprzedni element.

Weryfikacja:
- poz.1-3: 4,6,2 (parzyste, dl.3)
- poz.4-6: 7,3,5 (nieparzyste, dl.3)
- poz.7-12: 8,10,12,14,6,2 (parzyste, dl.6)
- poz.13-16: 3,7,1,9 (nieparzyste, dl.4)
- poz.17-18: 2,4 (parzyste, dl.2)
Najdluzsza: dl.6, poz.7, parzyste, elementy: 8 10 12 14 6 2.
